import{_ as i,l as n,o as e,c as l,v as t,p as s,x as o,d as p,i as d,S as c}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"编译执行","description":"","frontmatter":{"title":"编译执行","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/query-compilation.md","filePath":"cs/query-compilation.md","lastUpdated":1789023840000}'),h={name:"cs/query-compilation.md"};function m(E,a,A,u,_,f){const r=n("Mermaid");return e(),l("div",null,[a[1]||(a[1]=t('<h1 id="编译执行" tabindex="-1">编译执行 <a class="header-anchor" href="#编译执行" aria-label="Permalink to &quot;编译执行&quot;">​</a></h1><div class="epigraph"><p>把查询树编成循环与哈希调用，去掉算子间的虚函数与解释开关；计划变成一段代码，参数仍是绑定值。</p><footer>—— 据 Neumann, Efficiently Compiling Efficient Query Plans, VLDB 2011；HyPer；LegoBase 等</footer></div><p><a href="/cs/vectorized-execution">上一课</a>用批循环摊解释税。本课不规定批大小。缺口是再进一步：算子边界上的 <code>next</code> 即使按批仍有调度与分支。编译执行（query compilation）在优化之后生成机器码或低级 IR，push 模型（数据推进循环）常比拉模型更易熔合。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Volcano 解释器：多态 <code>next</code>、每算子一帧。编译：对具体类型、具体谓词生成代码，连接键比较是内联函数。缺口是<strong>编译延迟</strong>：OLTP 每次 1ms 的查询不能每次 LLVM 优化 100ms。策略：缓存编译结果（与计划缓存对齐）、解释短查询、只编译长 OLAP、或分层 JIT。</p><p>正确性：生成代码必须实现同一代数，含 NULL、三值、溢出。调试比解释器难，计划回归会表现为「同一 SQL 不同二进制」。</p><p><span class="marginnote">Thomas Neumann, VLDB 2011，HyPer 的数据中心代码生成。后续工作用 LLVM 或自定义 IR。本课不把某编译器版本当标准。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>从物理计划走代码生成：扫描循环、谓词、物化哈希表的 insert/probe 例程。push：扫描驱动，把行推进父的回调或内联体，减少返回。向量化与编译结合：生成的是批循环。</p><p>注册与安全：生成代码在引擎进程内执行，错误隔离（除零）要变成 SQL 错误不是进程崩溃。</p>',10)),(e(),s(c,null,{default:o(()=>[d(r,{id:"mermaid-28",class:"mermaid",graph:"flowchart%20TD%0A%20%20PLAN%5B%22%E7%89%A9%E7%90%86%E8%AE%A1%E5%88%92%22%5D%20--%3E%20CG%5B%22%E4%BB%A3%E7%A0%81%E7%94%9F%E6%88%90%22%5D%0A%20%20CG%20--%3E%20BIN%5B%22%E6%9C%BA%E5%99%A8%E7%A0%81%20%2F%20IR%22%5D%0A%20%20BIN%20--%3E%20CACHE%5B%22%E6%8C%89%E5%BD%A2%E7%8A%B6%E7%BC%93%E5%AD%98%22%5D%0A%20%20Q%5B%22%E7%9F%AD%E6%9F%A5%E8%AF%A2%22%5D%20--%3E%20INT%5B%22%E8%A7%A3%E9%87%8A%20%2F%20%E5%90%91%E9%87%8F%E5%8C%96%22%5D%0A%20%20Q%20--%3E%20CG%0A"})]),fallback:o(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>计划缓存键必须包含编译选项与类型。模式变更失效与预编译课相同。自适应重优化：要重新生成代码或回退解释器。代价模型：编译时间计入优化超时。</p><p>与存储过程：过程体是语句序列，每句可分别编译；跨语句循环仍在过程语言解释器里，除非整过程编译。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲外部排序算法——下一课。也不把 GPU/FPGA 代码生成写入必做。编译不是「一定更快」：极短点查，解释路径更短。</p><p>后课默认：长 OLAP 可编译；编译产物按计划形状缓存。外部排序是阻塞算子的经典落盘实现，与是否编译正交。</p><p>编译消灭算子调度，不消灭阻塞点：排序仍然要等输入尽。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>代码生成熔合算子，换编译时间与缓存复杂度。</li><li>短查询可解释；长查询才 JIT。</li><li>外部排序下一课：内存放不下时的阻塞算子。</li><li>出处：Neumann, VLDB 2011；HyPer；Graefe 执行背景。</li></ul>',9))])}const T=i(h,[["render",m]]);export{B as __pageData,T as default};
